def pre(balance, amount, overdraft):
    if balance < 0:
        return False
    if balance > 1000:
        return False
    if amount < 0:
        return False
    if amount > 1000:
        return False
    return True


def expected(balance, amount, overdraft):
    if amount <= 0:
        return None

    fee = 0
    if amount < 100:
        fee = 2

    new_balance = balance - amount - fee

    limit = 0
    if overdraft:
        limit = -500

    if new_balance < limit:
        return None

    return new_balance


def post(balance, amount, overdraft, result):
    expected_balance = expected(balance, amount, overdraft)

    if expected_balance == None:
        if result == None:
            return True
        return False

    if result == expected_balance:
        return True
    return False
